        if (kind == NodeId.scalar && implicit) {
            Pattern regexp;
            Tag tag;
            List<ResolverTuple> resolvers = value.isEmpty() ? this.yamlImplicitResolvers.get(Character.valueOf('�')) : this.yamlImplicitResolvers.get(Character.valueOf(value.charAt(0)));
