                for (ResolverTuple v : this.yamlImplicitResolvers.get(null)) {
                    tag = v.getTag();
                    regexp = v.getRegexp();
                    if (value.length() > v.getLimit() || !regexp.matcher(value).matches()) continue;
                    return tag;
                }
            }
        }
        switch (kind) {
            case scalar: {
                return Tag.STR;
