        this.fetchMoreTokens();
    }
    if (!this.tokens.isEmpty()) {
        if (choices.length == 0) {
            return true;
        }
        Token.ID first = this.tokens.get(0).getTokenId();
        for (int i = 0; i < choices.length; ++i) {
